[{"import": "pytest", "bot.py": "Signal\": \"BotTest(unittest.TestCase):", "test_mode_parsing": "def setUp(self)", "self.bot = Bot()": "def test_safe_mode(self)", "self.assertEqual(self.bot.mode, \"safe\", \"Safe mode defaults correctly\")": "def test_aggressive_mode(self)", "self.assertEqual(self.bot.mode, \"aggressive\", \"Aggressive mode parses correctly\")": "def test_degen_mode(self)", "self.assertEqual(self.bot.mode, \"degen\", \"Degen mode parses correctly\")": "def test_dry_run_default(self)", "self.assertFalse(self.bot.dry_run, \"Dry run should be False by default\")": "def test_dry_run_flag(self)", "self.assertTrue(self.bot.dry_run, \"Dry run should be True when --dry-run is set\")": "def test_window_timing(self)", "ts = self.bot.calculate_window_timestamp()": "self.assertEqual(ts % 300, 0, \"Window timestamp should be divisible by 300\")", "print(\"\\nBot tests passed!\")": "if __name__ == \"__main__\": \"pytest.main([\"-v\", \"test_bot.py\"])]"}]